// Dictionnaires plats fr/en/it/de — SANS bibliothèque (décision v2) : le
// routage localisé vient de Next lui-même, la traduction d'un hook de 20
// lignes (useT). Le français est la référence : toute clé absente d'une
// autre langue retombe dessus.

// POURQUOI IL N'Y A PLUS DE « ...fr » DANS en / it / de
//
// Chaque dictionnaire répète TOUTES les clés, même quand la traduction est
// identique au français. C'est volontairement redondant : hériter du français
// par « ...fr » rendait une clé oubliée invisible — elle compilait, et la page
// s'affichait en français chez un lecteur anglophone. Sans ce repli, le type
// Record<TranslationKey, string> exige les quatre langues, et « npx tsc » nomme
// la clé manquante avant qu'un utilisateur ne la découvre.

