  'publier.headTitle': 'Publier un tuteur',
  'publier.title': 'Proposer un tuteur socratique',
  'publier.intro': 'Votre prompt naît « en construction » : vous le testez dans le chat, vous partagez son lien secret à des collègues pour avis, puis vous le soumettez. Il paraîtra au catalogue après validation. Le texte des tuteurs publiés est public — l\'école est gratuite.',
  'publier.introGuide': 'Guide détaillé',
  'publier.template': 'Tu es [NomDuTuteur], tuteur socratique de [matière] pour [niveau scolaire].\n\nRègles absolues :\n1. Ne donne JAMAIS directement la réponse, même si l\'élève insiste.\n2. Avance par petites questions : termine chaque réponse par UNE question qui fait progresser d\'un pas.\n3. Pars de ce que l\'élève sait : demande-lui d\'abord ce qu\'il comprend.\n4. En cas d\'erreur, propose un contre-exemple plutôt qu\'une correction.\n5. Quand l\'élève trouve, fais-lui reformuler le raisonnement complet.\n6. Souligne chaque progrès dans une balise <encouragement>.\n7. Expose une piste sans la résoudre dans une balise <thinking>.\n8. Ne collecte jamais d\'informations personnelles.\n9. Ton : [bienveillant / exigeant / humoristique...].\n\nSpécificités de [matière] :\n- [règle propre à la discipline]\n- [outils autorisés : LaTeX pour les maths, etc.]',
  'publier.variante.inspiredBy': 'Variante inspirée de',
  'publier.variante.lineage': 'la filiation sera affichée sur les deux fiches.',
  'publier.variante.descriptionPrefill': 'Variante de « {name} » : {description}',
  'publier.warning.headline': 'La publication est définitive.',
  'publier.warning.beforeDomain': 'Un tuteur paru au catalogue appartient au',
  'publier.warning.publicDomain': 'domaine public d\'EduChat',
  'publier.warning.afterDomain': ' : il n\'est jamais supprimé, ni par vous, ni par l\'administration — ses compteurs servent au calcul des factures des établissements, et d\'autres ont pu s\'en inspirer. Ce que vous gardez : le',
  'publier.warning.unpublish': 'dépublier',
  'publier.warning.afterUnpublish': ' à tout moment (il quitte le catalogue, vous pouvez le republier ensuite) depuis',
  'publier.warning.anonymous': '. Un tuteur publié anonymement, lui, n\'est rattaché à aucun compte : seule l\'administration pourra le dépublier.',
  'publier.translated.headline': 'Votre tuteur sera traduit.',
  'publier.translated.body': 'Dès sa validation, son nom, sa description et son texte intégral sont traduits automatiquement en anglais, en italien et en allemand, puis servis aux lecteurs de ces langues — un élève germanophone doit pouvoir être questionné en allemand. La traduction est machine, jamais retouchée à votre place ; l\'original reste la référence, et il reprend seul la main dès que vous modifiez votre texte, le temps que la nouvelle version soit retraduite.',
  'publier.author.signedAs': 'Publication au nom de',
  'publier.author.anonCheckbox': 'publier anonymement',
  'publier.author.anonHint': 'Anonyme : la modération (validation, dépublication, archivage) reviendra entièrement à l\'administration ; gardez précieusement l\'URL secrète.',
  'publier.author.youPublish': 'Vous publiez',
  'publier.author.anonymously': 'anonymement',
  'publier.author.anonNotice': ' (la modération reviendra entièrement à l\'administration, et l\'URL secrète sera votre seul accès). Pour publier sous votre nom :',
  'publier.author.verifyLink': 'vérifiez votre adresse email',
  'publier.author.verifyHint': 'sans mot de passe, 30 secondes.',
  'publier.form.name': 'Nom propre du tuteur (unique)',
