  'tour.provider': 'The AI provider: choose who runs the tutor (Claude, ChatGPT, Mistral…). The green badge signals a possible GDPR framework, the red one a processor established outside Europe with no recognised framework. Providers set aside under the European AI Act are not in this list, and never come back from a school network.',
