  'tour.etab.identity': 'Your school, as the site knows it. The network addresses are still set by the site\'s administration; everything else — the hours, the quotas, the wallet, the invoice, the accounts and the school\'s tutors — is settled on this page, and nowhere else.',
  'tour.etab.hours': 'Free-access hours: outside these slots, the school key does not answer. Your simplest safeguard.',
  'tour.etab.quotas': 'Two limits: per pupil per day, then per school per month. The first curbs one pupil, the second protects the budget.',
  'tour.etab.usage': 'This month\'s usage, by provider. That figure feeds the invoice — you see it before the invoice does.',
  'tour.duel.mode': 'Two ways to compare: two tutors on one model, or one tutor on two models. The first refines a prompt, the second tests how robust it is.',
