  'tour.duel.question': 'The question goes to both columns at once: that is what makes the comparison honest.',
  'tour.duel.send': 'Send. These trial conversations are never kept: the duel is a workshop, not a history.',
  'tour.compte.usage': 'What the server knows of your usage — and above all what it does not: a personal key is never logged. A teacher also sees the tokens of their class sessions, billed to the school.',
