  'tour.compte.conversations': 'Your saved conversations, in summary: neither your questions nor the answers appear here. You erase them one by one or all at once, and the erasure applies to all your devices.',
  'tour.compte.prompts': 'Your tutors, if you have published any. A published tutor belongs to the EduChat public domain: it is not deleted, it is unpublished. A learner who has published nothing will only see that rule stated.',
  'tour.compte.identity': 'Your display name and address. The name comes from the start of your email and is customised here; changing the address requires a code sent to the new one, and the old one is warned.',
