  'publier.headTitle': 'Publish a tutor',
  'publier.title': 'Propose a Socratic tutor',
  'publier.intro': 'Your prompt starts out “under construction”: you test it in the chat, you share its secret link with colleagues for feedback, then you submit it. It will appear in the catalogue once approved. The text of published tutors is public — school is free.',
  'publier.introGuide': 'Detailed guide',
  'publier.template': 'You are [TutorName], a Socratic tutor of [subject] for [school level].\n\nAbsolute rules:\n1. NEVER give the answer directly, even if the learner insists.\n2. Move forward in small questions: end every reply with ONE question that takes things one step further.\n3. Start from what the learner knows: ask first what they understand.\n4. When they are wrong, offer a counter-example rather than a correction.\n5. When the learner gets it, have them restate the whole line of reasoning.\n6. Highlight every step forward in an <encouragement> tag.\n7. Set out a lead without resolving it in a <thinking> tag.\n8. Never collect personal information.\n9. Tone: [kind / demanding / humorous...].\n\nSpecifics of [subject]:\n- [rule particular to the discipline]\n- [permitted tools: LaTeX for maths, etc.]',
  'publier.variante.inspiredBy': 'Variant inspired by',
  'publier.variante.lineage': 'the lineage will be shown on both tutor pages.',
  'publier.variante.descriptionPrefill': 'Variant of “{name}”: {description}',
  'publier.warning.headline': 'Publication is final.',
  'publier.warning.beforeDomain': 'A tutor that has appeared in the catalogue belongs to the',
  'publier.warning.publicDomain': 'EduChat public domain',
  'publier.warning.afterDomain': ': it is never deleted, neither by you nor by the administration — its counters feed the billing of schools, and others may have drawn on it. What you keep: the ability to',
  'publier.warning.unpublish': 'unpublish',
  'publier.warning.afterUnpublish': ' it at any time (it leaves the catalogue, and you can republish it later) from',
  'publier.warning.anonymous': '. A tutor published anonymously, on the other hand, is attached to no account: only the administration will be able to unpublish it.',
  'publier.translated.headline': 'Your tutor will be translated.',
  'publier.translated.body': 'As soon as it is approved, its name, its description and its full text are automatically translated into the site\'s three other languages, then served to readers in those languages — a German-speaking learner should be able to be questioned in German. The translation is machine-made and never touched up on your behalf; the original remains the reference, and it takes over again on its own as soon as you edit your text, until the new version has been retranslated.',
  'publier.author.signedAs': 'Publishing as',
  'publier.author.anonCheckbox': 'publish anonymously',
  'publier.author.anonHint': 'Anonymous: moderation (approval, unpublishing, archiving) will rest entirely with the administration; keep the secret URL safe.',
  'publier.author.youPublish': 'You are publishing',
  'publier.author.anonymously': 'anonymously',
  'publier.author.anonNotice': ' (moderation will rest entirely with the administration, and the secret URL will be your only way in). To publish under your own name:',
  'publier.author.verifyLink': 'verify your email address',
  'publier.author.verifyHint': 'no password, 30 seconds.',
