  'etab.signup.ipsHint': 'Comma-separated; ranges (203.0.113.0/24) are not recognised. Your students are recognised as yours at these addresses. We have prefilled the one you are writing from — correct it if you are not at the school. An address already claimed by another school is refused. You may leave this empty: any later change goes through the administration.',
