  'etab.signup.warningTitle': 'Before you confirm.',
  'etab.signup.warning': 'Your school\'s wallet starts at ZERO: no student will be able to use the school\'s AI key until it is topped up. No payment method is wired up yet — write to us to arrange a top-up. In the meantime anyone can use their own AI key, and nothing is billed to you.',
