  'tour.history': 'Lo storico: le Sue conversazioni restano in questo browser — e sono salvate sul Suo account, se ne ha uno. Nuova discussione, importazione, esportazione del profilo: tutto qui.',
  'tour.provider': 'Il fornitore di IA: scelga chi fa funzionare il tutor (Claude, ChatGPT, Mistral…). Il contrassegno verde segnala un possibile quadro GDPR, quello rosso un responsabile del trattamento con sede fuori dall\'Europa senza quadro riconosciuto. I fornitori esclusi in virtù del regolamento europeo sull\'IA non figurano in questo elenco, e non tornano mai da una rete scolastica.',
