  'tour.composer': 'L\'area di scrittura: ponga qui la Sua domanda — il tutor non darà la risposta, La guiderà con domande.',
  'tour.attach': 'La graffetta: alleghi un\'immagine o un PDF alla Sua domanda (secondo il fornitore), con la Sua chiave personale.',
  'tour.voice': 'Il microfono: detti la Sua domanda, e la modalità vocale legge le risposte ad alta voce — ideale sullo smartphone.',
  'tour.send': 'Il pulsante di invio: la Sua domanda parte verso il tutor.',
  'tour.tokens': 'Il contatore di token: il volume totale consumato da questo dispositivo, tutti i fornitori inclusi.',
  'tour.session.state': 'Lo stato dell\'aula: aperta o chiusa, per quale istituto e fino a che ora. La prima occhiata del mattino.',
  'tour.session.password': 'La password della scuola. È lei, e solo lei, ad aprire l\'accesso alla chiave dell\'istituto per tutti gli allievi dell\'aula.',
  'tour.session.duration': 'La durata: l\'accesso si richiude da solo alla fine. Nulla da ricordare andando via.',
  'tour.session.open': 'Aprire l\'accesso. Da quel momento gli allievi dell\'aula dialogano senza account e senza chiave: paga la scuola.',
  'tour.session.tutor': 'Il tutor assegnato alla classe: tutti gli allievi partono con questo, senza cercarlo nel catalogo.',
  'tour.session.web': 'La ricerca web, da autorizzare o meno per questa lezione. Costa token e spesso distoglie dal ragionamento.',
  'tour.session.deploy': 'Distribuire: la scelta vale subito per tutta l\'aula, fino alla fine della lezione.',
  'tour.etab.identity': 'Il Suo istituto, così come il sito lo conosce. Gli indirizzi di rete restano fissati dall\'amministrazione del sito; tutto il resto — gli orari, le quote, il portafoglio, la fattura, gli account e i tutor della scuola — si regola su questa pagina, e in nessun altro luogo.',
  'tour.etab.hours': 'Gli orari di accesso libero: fuori da queste fasce, la chiave della scuola non risponde. La Sua protezione più semplice.',
  'tour.etab.quotas': 'Due limiti: per allievo al giorno, poi per la scuola al mese. Il primo frena il singolo, il secondo protegge il budget.',
  'tour.etab.usage': 'Il consumo del mese, per fornitore. È questa cifra a fare la fattura: la vede prima che arrivi.',
  'tour.duel.mode': 'Due modi di confrontare: due tutor sullo stesso modello, o lo stesso tutor su due modelli. Il primo affina un prompt, il secondo ne prova la solidità.',
  'tour.duel.columnA': 'La configurazione delle due colonne: tutor, fornitore, modello. È l\'unico punto del sito dove si nomina ancora un modello: è proprio lo scopo del duello.',
  'tour.duel.columnB': 'Le due risposte, affiancate e in diretta. È leggendole insieme che una formulazione si rivela migliore dell\'altra.',
  'tour.duel.question': 'La domanda parte in entrambe le colonne insieme: è questo a rendere onesto il confronto.',
  'tour.duel.send': 'Invii. Queste conversazioni di prova non vengono mai conservate: il duello è un laboratorio, non uno storico.',
  'tour.compte.usage': 'Ciò che il server sa del Suo consumo — e soprattutto ciò che ignora: una chiave personale non viene mai registrata. Un insegnante vede in più i token delle sue lezioni, fatturati alla scuola.',
  'tour.compte.keys': 'Le chiavi API che ha chiesto esplicitamente di memorizzare. Il server non può mostrargliele — le conserva cifrate — ma può dimenticarle, con un clic e per fornitore.',
  'tour.compte.conversations': 'Le Sue conversazioni salvate, in sintesi: qui non compaiono né le domande né le risposte. Le cancella una per una o tutte, e la cancellazione vale per tutti i Suoi dispositivi.',
  'tour.compte.prompts': 'I Suoi tutor, se ne ha pubblicati. Un tutor pubblicato appartiene al dominio pubblico di EduChat: non si elimina, si depubblica. Un allievo che non ha pubblicato nulla vedrà solo l\'enunciato di questa regola.',
  'tour.compte.identity': 'Il Suo nome visualizzato e il Suo indirizzo. Il nome viene dall\'inizio della Sua email e si personalizza qui; cambiare indirizzo richiede un codice inviato al nuovo, e il vecchio ne viene avvisato.',
  'tour.compte.export': '« Esporta tutto » riunisce ciò che conserva il server e ciò che conserva questo browser, in un unico file. Per l\'amministrazione, questo pulsante lascia il posto a « Amministrare » — l\'esportazione resta accanto.',
  'tour.admin.validation': 'La coda di validazione. Un tutor proposto attende una rilettura — e qualsiasi promptagogo verificato può pubblicarlo, non solo l\'amministrazione: così si evita il collo di bottiglia di un unico validatore.',
  'tour.admin.prompts': 'Tutti i tutor, in qualsiasi stato. Nulla viene mai eliminato: pubblicato, si depubblica o si modifica; depubblicato, si ripubblica o si archivia. La fatturazione dei token deve restare calcolabile.',
  'tour.admin.accounts': 'Gli account. Nessuna password esiste: l\'identità si prova con un codice ricevuto via email. Qui si spuntano i ruoli e si collega un insegnante alla sua scuola — gli allievi non hanno mai un account.',
  'tour.admin.schools': 'Gli istituti clienti. Una scuola è riconosciuta dai suoi indirizzi di rete: i suoi allievi entrano senza account né chiave. Orari e quote si regolano lato scuola; IP e fatturazione restano amministrativi.',
  'tour.admin.ladder': 'La scala dei modelli. L\'allievo sceglie solo un fornitore; qui si decidono i tre gradini, dal più economico al più approfondito. Un gradino che l\'editore non pubblica più viene segnalato.',
  'tour.admin.billing': 'La fatturazione, in token per fornitore — la tariffa resta in mano al gestore. Solo la chiave interna è fatturata: l\'uso di una chiave personale non viene mai registrato, e la demo pubblica appare a parte.',
  'tour.hint': 'Clic o → per avanzare · spazio: pausa · Esc: uscire',
  'tour.prev': 'Passo precedente',
  'tour.next': 'Passo successivo',
