  'publier.headTitle': 'Pubblicare un tutor',
  'publier.title': 'Proporre un tutor socratico',
  'publier.intro': 'Il Suo prompt nasce « in costruzione »: lo prova nella chat, ne condivide il link segreto con i colleghi per un parere, poi lo sottopone. Comparirà nel catalogo dopo la convalida. Il testo dei tutor pubblicati è pubblico — la scuola è gratuita.',
  'publier.introGuide': 'Guida dettagliata',
  'publier.template': 'Sei [NomeDelTutor], tutor socratico di [materia] per [livello scolastico].\n\nRegole assolute:\n1. Non dare MAI direttamente la risposta, anche se l\'allievo insiste.\n2. Procedi per piccole domande: concludi ogni risposta con UNA domanda che faccia avanzare di un passo.\n3. Parti da ciò che l\'allievo sa: chiedigli prima che cosa ha capito.\n4. In caso di errore, proponi un controesempio anziché una correzione.\n5. Quando l\'allievo trova, fagli riformulare l\'intero ragionamento.\n6. Sottolinea ogni progresso in un tag <encouragement>.\n7. Esponi una pista senza risolverla in un tag <thinking>.\n8. Non raccogliere mai informazioni personali.\n9. Tono: [benevolo / esigente / umoristico...].\n\nSpecificità di [materia]:\n- [regola propria alla disciplina]\n- [strumenti consentiti: LaTeX per la matematica, ecc.]',
  'publier.variante.inspiredBy': 'Variante ispirata a',
  'publier.variante.lineage': 'la filiazione sarà indicata su entrambe le schede.',
  'publier.variante.descriptionPrefill': 'Variante di « {name} »: {description}',
  'publier.warning.headline': 'La pubblicazione è definitiva.',
  'publier.warning.beforeDomain': 'Un tutor comparso nel catalogo appartiene al',
  'publier.warning.publicDomain': 'dominio pubblico di EduChat',
  'publier.warning.afterDomain': ': non viene mai eliminato, né da Lei né dall\'amministrazione — i suoi contatori servono al calcolo delle fatture degli istituti, e altri possono essersene ispirati. Ciò che Le resta: la possibilità di',
  'publier.warning.unpublish': 'depubblicarlo',
  'publier.warning.afterUnpublish': ' in qualsiasi momento (esce dal catalogo e potrà ripubblicarlo in seguito) dalla pagina',
  'publier.warning.anonymous': '. Un tutor pubblicato in forma anonima, invece, non è collegato ad alcun account: solo l\'amministrazione potrà depubblicarlo.',
  'publier.translated.headline': 'Il Suo tutor sarà tradotto.',
  'publier.translated.body': 'Non appena convalidato, il suo nome, la sua descrizione e il suo testo integrale vengono tradotti automaticamente nelle altre tre lingue del sito e proposti ai lettori di quelle lingue — un allievo germanofono deve poter essere interrogato in tedesco. La traduzione è automatica, mai ritoccata al Suo posto; l\'originale resta il riferimento e riprende da solo il sopravvento non appena Lei modifica il testo, il tempo che la nuova versione venga ritradotta.',
  'publier.author.signedAs': 'Pubblicazione a nome di',
  'publier.author.anonCheckbox': 'pubblicare in forma anonima',
  'publier.author.anonHint': 'Anonimo: la moderazione (convalida, depubblicazione, archiviazione) spetterà interamente all\'amministrazione; conservi con cura l\'URL segreto.',
  'publier.author.youPublish': 'Sta pubblicando',
  'publier.author.anonymously': 'in forma anonima',
  'publier.author.anonNotice': ' (la moderazione spetterà interamente all\'amministrazione e l\'URL segreto sarà il Suo unico accesso). Per pubblicare a Suo nome:',
  'publier.author.verifyLink': 'verifichi il Suo indirizzo email',
