  'admin.credit.rateHelp': 'Lei sceglie quanto dare, tra il {min} e il {max} %. Al {min} %, il Suo contributo copre le sole spese d\'incasso: l\'hosting è allora pagato dall\'autore. Oltre, finanzia anche la gratuità — la dimostrazione pubblica, gli istituti RESPIRE e i paesi che non possono pagare. Quanto imposta qui si applica allo scalo di ogni chiamata.',
