  'session.deploy.providersHint': 'Queste caselle valgono soltanto per la chiave dell\'istituto: un allievo che porta la propria chiave non ne dipende. Selezionare tutto non restringe nulla; deselezionare tutto chiude la chiave dell\'istituto fino al termine della sessione. L\'impostazione scade con lo sblocco dell\'aula.',
  'session.state.providers': 'Fornitori ammessi:',
