  'etab.signup.pitch': 'Non dispone ancora di uno spazio responsabile. Se il Suo istituto non è ancora iscritto, lo iscriva: ne diventerà subito il responsabile, senza alcuna convalida preventiva da parte nostra.',
  'etab.signup.authHint': 'È anche il primo passo per iscrivere il Suo istituto: si identifichi e il pulsante di iscrizione comparirà qui.',
  'etab.signup.cta': 'Iscrivere il mio istituto',
  'etab.signup.formTitle': 'Iscrizione del Suo istituto',
  'etab.signup.name': 'Nome dell\'istituto',
  'etab.signup.namePlaceholder': 'es. Scuola media di Bellevue',
  'etab.signup.ips': 'Indirizzi IP di riconoscimento',
  'etab.signup.ipsHint': 'Separati da virgole; gli intervalli (203.0.113.0/24) non sono riconosciuti. È a questi indirizzi che i Suoi allievi verranno riconosciuti come Suoi. Abbiamo precompilato quello da cui ci sta scrivendo — lo corregga se non si trova a scuola. Un indirizzo già rivendicato da un altro istituto viene rifiutato. Può lasciare vuoto: ogni modifica successiva passerà dall\'amministrazione.',
