  'etab.signup.addressHint': 'Indirizzo postale del servizio che salda le fatture. Le fatture e gli avvisi, invece, saranno inviati all\'indirizzo email che ha appena verificato.',
  'etab.signup.warningTitle': 'Da sapere prima di confermare.',
  'etab.signup.warning': 'Il portafoglio del Suo istituto parte da ZERO: nessun allievo potrà usare la chiave IA della scuola finché non verrà ricaricato. Nessun mezzo di pagamento è ancora collegato — ci scriva per concordare una ricarica. Nel frattempo ognuno può usare la propria chiave IA e non Le viene fatturato nulla.',
  'etab.signup.submit': 'Creare il mio istituto',
