  'etab.signup.err.ipTaken': 'Uno di questi indirizzi IP è già rivendicato da un altro istituto. Lo tolga, oppure contatti l\'amministrazione se è davvero il Suo.',
  'etab.signup.err.name': 'Il nome dell\'istituto è obbligatorio.',
