  'chat.input.wrng.title': 'Auftragsverarbeiter ausserhalb der EU ohne anerkannten Übermittlungsrahmen: Ihre Eingaben können gespeichert und weiterverwendet werden. Nur für NICHT personenbezogene Inhalte. Siehe Datenschutzseite.',
