  'chat.input.rememberThis': 'Diesen merken',
  'chat.input.keySaved': 'Schlüssel gemerkt ✓',
  'chat.input.keySavedTitle': 'Für diesen Anbieter ist ein Schlüssel gespeichert: Feld leer lassen, um ihn zu verwenden.',
  'tour.title': 'Geführte Tour durch die Oberfläche',
  'tour.launch': 'Interaktive Tour durch die Oberfläche starten',
  'tour.tutor': 'Das Tutor-Banner: Es zeigt, welcher sokratische Tutor das Gespräch führt und seine Version — klicken Sie auf den Namen für seine Seite.',
  'tour.messages': 'Der Gesprächsbereich: Ihre Fragen und die Antworten des Tutors erscheinen hier — live, während sie entstehen.',
  'tour.history': 'Der Verlauf: Ihre Gespräche bleiben in diesem Browser — und werden auf Ihrem Konto gesichert, falls Sie eines haben. Neues Gespräch, Import, Profil-Export: alles hier.',
  'tour.provider': 'Der KI-Anbieter: Wählen Sie, wer den Tutor betreibt (Claude, ChatGPT, Mistral…). Das grüne Abzeichen weist auf einen möglichen DSGVO-Rahmen hin, das rote auf einen Auftragsverarbeiter ausserhalb Europas ohne anerkannten Rahmen. Anbieter, die nach der europäischen KI-Verordnung ausgeschlossen sind, stehen nicht in dieser Liste und kehren aus einem Schulnetz nie zurück.',
  'tour.model': 'Das Modell: Sobald Ihr Schlüssel eingetragen ist, zeigt die Liste die Modelle, die der Anbieter selbst nennt — und Sie können weiterhin einen anderen eintippen.',
  'tour.reasoning': 'Die Denktiefe: schnell, ausgewogen oder gründlich. Je gründlicher, desto besser das Denken — und desto mehr Tokens kostet es.',
  'tour.apikey': 'Ihr eigener API-Schlüssel: Er bleibt auf der Seite und wird nur gemerkt, wenn Sie „Schlüssel merken“ ankreuzen (Konto nötig, verschlüsselte Ablage). Er schaltet auch Anhänge und Sprachchat frei.',
  'tour.composer': 'Das Eingabefeld: Stellen Sie hier Ihre Frage — der Tutor gibt keine Antwort vor, er führt Sie mit Fragen.',
  'tour.attach': 'Die Büroklammer: Hängen Sie ein Bild oder PDF an Ihre Frage an (je nach Anbieter), mit Ihrem eigenen Schlüssel.',
  'tour.voice': 'Das Mikrofon: Diktieren Sie Ihre Frage — der Sprachmodus liest Antworten laut vor. Ideal auf dem Smartphone.',
  'tour.send': 'Der Senden-Knopf: Ihre Frage geht an den Tutor.',
  'tour.tokens': 'Der Token-Zähler: das Gesamtvolumen, das von diesem Gerät verbraucht wurde, alle Anbieter zusammen.',
  'tour.session.state': 'Der Zustand des Raums: offen oder geschlossen, für welche Schule und bis wann. Der erste Blick am Morgen.',
  'tour.session.password': 'Das Schulpasswort. Nur es öffnet den Zugang zum Schulschlüssel für alle Lernenden im Raum.',
  'tour.session.duration': 'Die Dauer: Der Zugang schliesst sich am Ende von selbst. Nichts, woran man beim Gehen denken muss.',
  'tour.session.open': 'Zugang öffnen. Ab dann arbeiten die Lernenden ohne Konto und ohne Schlüssel: Die Schule zahlt.',
  'tour.session.tutor': 'Der für die Klasse bereitgestellte Tutor: Alle starten mit diesem, ohne ihn im Katalog zu suchen.',
  'tour.session.web': 'Die Websuche, für diese Stunde erlaubt oder nicht. Sie kostet Token und lenkt oft vom Denken ab.',
  'tour.session.deploy': 'Bereitstellen: Die Wahl gilt sofort für den ganzen Raum, bis zum Ende der Stunde.',
  'tour.etab.identity': 'Ihre Schule, so wie die Website sie kennt. Die Netzwerkadressen setzt weiterhin die Verwaltung der Website; alles Übrige — Zeiten, Kontingente, Guthaben, Rechnung, Konten und die Tutoren der Schule — wird auf dieser Seite geregelt und sonst nirgends.',
  'tour.etab.hours': 'Die Zeiten des freien Zugangs: ausserhalb dieser Fenster antwortet der Schulschlüssel nicht. Ihr einfachster Schutz.',
  'tour.etab.quotas': 'Zwei Grenzen: pro Lernendem und Tag, dann pro Schule und Monat. Die erste bremst Einzelne, die zweite schützt das Budget.',
  'tour.etab.usage': 'Der Monatsverbrauch je Anbieter. Diese Zahl ergibt die Rechnung — Sie sehen sie vorher.',
  'tour.duel.mode': 'Zwei Vergleichsarten: zwei Tutoren auf einem Modell, oder ein Tutor auf zwei Modellen. Das erste verfeinert einen Prompt, das zweite prüft seine Robustheit.',
  'tour.duel.columnA': 'Die Konfiguration beider Spalten: Tutor, Anbieter, Modell. Der einzige Ort, an dem noch ein Modell benannt wird — genau darum geht es im Duell.',
  'tour.duel.columnB': 'Die zwei Antworten, nebeneinander und live. Erst im Vergleich zeigt sich, welche Formulierung besser ist.',
  'tour.duel.question': 'Die Frage geht gleichzeitig in beide Spalten: Das macht den Vergleich ehrlich.',
  'tour.duel.send': 'Senden. Diese Probegespräche werden nie aufbewahrt: Das Duell ist eine Werkstatt, kein Verlauf.',
  'tour.compte.usage': 'Was der Server über Ihren Verbrauch weiss — und vor allem, was nicht: Ein persönlicher Schlüssel wird nie protokolliert. Eine Lehrperson sieht zusätzlich die Token ihrer Unterrichtsstunden, die der Schule berechnet werden.',
  'tour.compte.keys': 'Die API-Schlüssel, deren Speicherung Sie ausdrücklich verlangt haben. Der Server kann sie Ihnen nicht zeigen — er hält sie verschlüsselt — aber er kann sie vergessen, per Klick und je Anbieter.',
  'tour.compte.conversations': 'Ihre gesicherten Gespräche in der Übersicht: Weder Ihre Fragen noch die Antworten erscheinen hier. Sie löschen sie einzeln oder alle, und das Löschen gilt für alle Ihre Geräte.',
  'tour.compte.prompts': 'Ihre Tutoren, falls Sie welche veröffentlicht haben. Ein veröffentlichter Tutor gehört zur Allmende von EduChat: Er wird nicht gelöscht, sondern zurückgezogen. Wer nichts veröffentlicht hat, sieht hier nur diese Regel.',
  'tour.compte.identity': 'Ihr angezeigter Name und Ihre Adresse. Der Name stammt vom Anfang Ihrer E-Mail und wird hier angepasst; ein Adresswechsel verlangt einen Code an die neue Adresse, und die alte wird benachrichtigt.',
  'tour.compte.export': '„Alles exportieren“ vereint in einer Datei, was der Server und was dieser Browser aufbewahrt. Für die Verwaltung weicht diese Schaltfläche „Verwalten“ — der Export bleibt daneben.',
  'tour.admin.validation': 'Die Prüfliste. Ein vorgeschlagener Tutor wartet hier — und jede bestätigte Promptagogin darf ihn veröffentlichen, nicht nur die Verwaltung: Das vermeidet den Engpass einer einzigen Prüfinstanz.',
  'tour.admin.prompts': 'Alle Tutoren, in jedem Zustand. Nichts wird je gelöscht: veröffentlicht — zurückziehen oder bearbeiten; zurückgezogen — wieder veröffentlichen oder archivieren. Die Token-Abrechnung muss berechenbar bleiben.',
  'tour.admin.accounts': 'Die Konten. Es gibt kein Passwort: Die Identität wird per E-Mail-Code nachgewiesen. Hier werden Rollen gesetzt und Lehrpersonen ihrer Schule zugeordnet — Lernende haben nie ein Konto.',
  'tour.admin.schools': 'Die Kundenschulen. Eine Schule wird an ihren Netzadressen erkannt: Ihre Lernenden treten ohne Konto und ohne Schlüssel ein. Zeiten und Kontingente regelt die Schule; IP und Abrechnung bleiben Verwaltungssache.',
  'tour.admin.ladder': 'Die Modellleiter. Lernende wählen nur einen Anbieter; hier werden die drei Stufen festgelegt, von sparsam bis gründlich. Eine Stufe, die der Anbieter nicht mehr führt, wird markiert.',
  'tour.admin.billing': 'Die Abrechnung, in Token je Anbieter — der Tarif bleibt Sache der Verwaltung. Nur der interne Schlüssel wird berechnet: Die Nutzung eines persönlichen Schlüssels wird nie protokolliert, und die öffentliche Demo erscheint gesondert.',
  'tour.hint': 'Klick oder → zum Weitergehen · Leertaste: Pause · Esc: Beenden',
  'tour.prev': 'Vorheriger Schritt',
  'tour.next': 'Nächster Schritt',
  'tour.pause': 'Pause',
  'tour.resume': 'Fortsetzen',
  'tour.quit': 'Tour beenden',
