  'compte.usage.notMeasured': 'EduChat misst Ihren persönlichen Verbrauch nicht: Wenn Sie Ihren eigenen API-Schlüssel verwenden, wird nichts protokolliert — weder die Frage noch die Antwort noch die Anzahl der Token. Die folgenden Zahlen sind die einzigen, die der Server kennt.',
