  'admin.prompts.helpRetiredRest': ': wieder veröffentlichen · archivieren — um einen zurückgezogenen Tutor zu überarbeiten, veröffentlichen Sie ihn zuerst wieder. „Bearbeiten“ umfasst Name, Beschreibung und Text; wird der TEXT geändert, entsteht eine neue Version (Name und Beschreibung werden an Ort und Stelle korrigiert). Um von einem Tutor auszugehen, ohne ihn anzurühren, öffnen Sie „Bearbeiten“ und dann „Duplizieren“ — veröffentlichen Sie ihn also zuerst wieder, falls er zurückgezogen ist. Archivieren räumt nur diese Liste auf — der Tutor bleibt mit seinen Zählern in der Datenbank, und die Abrechnung bleibt berechenbar.',
