  'admin.ladder.help1': 'Was die lernende Person erhält, wenn sie einen Anbieter wählt. Es beginnt IMMER auf Sprosse 1, der sparsamsten; die Schaltfläche „Neu erzeugen“ einer Antwort steigt eine Stufe höher. Der Modellname wird Lernenden nicht mehr gezeigt — nur Promptagoginnen und Promptagogen behalten ein ausdrückliches Feld Modell. Bleiben die drei Felder leer, gilt wieder der ursprüngliche Vorschlag.',
