  'session.intro': 'Öffnen Sie den Zugang zum API-Schlüssel der Schule für alle Lernenden in diesem Raum: kein Konto, kein persönlicher Schlüssel nötig. Der Zugang schliesst sich am Ende der gewählten Dauer von selbst.',
