  'prompt.versions': 'Versionen',
  'prompt.versionLine': 'v{v} — {date} — {size} KB',
  'publier.headTitle': 'Tutor veröffentlichen',
  'publier.title': 'Einen sokratischen Tutor vorschlagen',
  'publier.intro': 'Ihr Prompt entsteht „im Aufbau“: Sie testen ihn im Chat, teilen seinen geheimen Link mit Kolleginnen und Kollegen für eine Rückmeldung und reichen ihn dann ein. Nach der Freigabe erscheint er im Katalog. Der Text veröffentlichter Tutoren ist öffentlich — die Schule ist gratis.',
  'publier.introGuide': 'Ausführlicher Leitfaden',
  'publier.template': 'Du bist [TutorName], sokratischer Tutor für [Fach] auf [Schulstufe].\n\nAbsolute Regeln:\n1. Gib NIE direkt die Antwort, auch wenn die Lernenden darauf beharren.\n2. Gehe in kleinen Fragen vor: Schliesse jede Antwort mit EINER Frage ab, die einen Schritt weiterführt.\n3. Geh von dem aus, was die Lernenden wissen: Frage zuerst, was sie verstanden haben.\n4. Biete bei einem Fehler ein Gegenbeispiel an statt einer Korrektur.\n5. Wenn die Lernenden es finden, lass sie den ganzen Gedankengang neu formulieren.\n6. Hebe jeden Fortschritt in einem <encouragement>-Tag hervor.\n7. Zeige eine Spur auf, ohne sie zu lösen, in einem <thinking>-Tag.\n8. Sammle nie persönliche Informationen.\n9. Ton: [wohlwollend / fordernd / humorvoll...].\n\nBesonderheiten von [Fach]:\n- [fachspezifische Regel]\n- [erlaubte Hilfsmittel: LaTeX für Mathematik usw.]',
  'publier.variante.inspiredBy': 'Variante, inspiriert von',
  'publier.variante.lineage': 'die Abstammung wird bei beiden Tutoren angezeigt.',
  'publier.variante.descriptionPrefill': 'Variante von „{name}“: {description}',
  'publier.warning.headline': 'Die Veröffentlichung ist endgültig.',
  'publier.warning.beforeDomain': 'Ein im Katalog erschienener Tutor gehört zur',
  'publier.warning.publicDomain': 'Allmende von EduChat',
  'publier.warning.afterDomain': ': Er wird nie gelöscht, weder von Ihnen noch von der Verwaltung — seine Zähler dienen der Abrechnung der Schulen, und andere könnten sich davon inspiriert haben. Was Ihnen bleibt: Sie können ihn jederzeit',
  'publier.warning.unpublish': 'zurückziehen',
  'publier.warning.afterUnpublish': ' (er verlässt den Katalog, Sie können ihn später wieder veröffentlichen) — und zwar über',
  'publier.warning.anonymous': '. Ein anonym veröffentlichter Tutor ist dagegen keinem Konto zugeordnet: Nur die Verwaltung kann ihn zurückziehen.',
  'publier.translated.headline': 'Ihr Tutor wird übersetzt.',
  'publier.translated.body': 'Sobald er freigegeben ist, werden sein Name, seine Beschreibung und sein vollständiger Text automatisch in die drei anderen Sprachen der Website übersetzt und den Leserinnen und Lesern dieser Sprachen ausgeliefert — eine italienischsprachige Lernende soll auf Italienisch befragt werden können. Die Übersetzung ist maschinell und wird nie an Ihrer Stelle überarbeitet; das Original bleibt die Referenz und übernimmt von selbst wieder, sobald Sie Ihren Text ändern, bis die neue Fassung neu übersetzt ist.',
  'publier.author.signedAs': 'Veröffentlichung im Namen von',
  'publier.author.anonCheckbox': 'anonym veröffentlichen',
  'publier.author.anonHint': 'Anonym: Die Moderation (Freigabe, Zurückziehen, Archivierung) liegt vollständig bei der Verwaltung; bewahren Sie die geheime URL gut auf.',
  'publier.author.youPublish': 'Sie veröffentlichen',
  'publier.author.anonymously': 'anonym',
  'publier.author.anonNotice': ' (die Moderation liegt vollständig bei der Verwaltung, und die geheime URL ist Ihr einziger Zugang). Um unter Ihrem Namen zu veröffentlichen:',
  'publier.author.verifyLink': 'verifizieren Sie Ihre E-Mail-Adresse',
  'publier.author.verifyHint': 'ohne Passwort, 30 Sekunden.',
  'publier.form.name': 'Eigenname des Tutors (eindeutig)',
  'publier.form.namePlaceholder': 'z. B. Pythagoras, Curie, Erasmus…',
  'publier.form.language': 'Hauptsprache',
  'publier.lang.fr': 'Français',
