  'publier.lang.it': 'Italiano',
  'publier.lang.de': 'Deutsch',
  'publier.form.description': 'Beschreibung (Fach, Stufe, Ansatz — im Katalog sichtbar)',
  'publier.form.descriptionPlaceholder': 'z. B. Physik-Tutor für die Matura: lässt Argumentationen über Gedankenexperimente aufbauen.',
  'publier.form.body': 'Der System-Prompt (max. 256 KB — die Vorlage unten ist ein Ausgangspunkt, passen Sie alles an)',
  'publier.form.webSearch': 'Websuche für diesen Tutor erlauben (für einen Denk-Tutor nicht empfohlen — kostet Tokens)',
  'publier.form.creating': 'Wird erstellt…',
  'publier.form.submit': 'Entwurf erstellen (vor der Veröffentlichung testbar)',
  'publier.err.nameInvalid': 'Der Name muss ein Eigenname sein: 2 bis 64 Zeichen (Buchstaben, Ziffern, Leerzeichen, Bindestriche). „essai“ ist reserviert.',
  'publier.err.nameTaken': 'Dieser Name ist bereits vergeben — jeder Tutor hat einen eindeutigen Eigennamen.',
  'publier.err.bodyTooShort': 'Der Prompt ist zu kurz für einen echten Tutor.',
