  'essai.headTitle': 'Test: {name}',
  'essai.banner.draft.pre': 'Dieser Prompt ist',
  'essai.banner.draft.rest': '— im Katalog unsichtbar. Über diesen geheimen Link lässt er sich lesen und testen: Teilen Sie ihn mit Ihren Testpersonen.',
