  'essai.banner.retired.rest': '— nichts wird gelöscht, sein Autor kann ihn unten wieder veröffentlichen.',
  'essai.publishWarning.pre': 'Das Einreichen ist der Punkt ohne Wiederkehr: Nach der Prüfung gehört dieser Tutor zur',
  'essai.publishWarning.strong': 'Allmende von EduChat',
  'essai.publishWarning.rest': 'und wird nie gelöscht. Er lässt sich weiterhin zurückziehen (Rückzug aus dem Katalog, umkehrbar); seine Verbrauchszähler bleiben jedoch erhalten.',
  'essai.action.test': 'Im Chat testen',
