  'ecole.active.teacher': 'Mitglied',
  'ecole.active.teacherTitle': 'Sie gehören zu dieser Schule, ohne sie zu administrieren: die Einstellungen werden angezeigt, bleiben aber schreibgeschützt.',
  'ecole.active.hint': 'Ein Wechsel der Schule ändert alles Folgende.',
  'zone.adminOnly': 'Nur Administratorinnen und Administratoren',
  'zone.adminOnlyTitle': 'Abschnitt nur für Administratorinnen und Administratoren der aktiven Schule: Ihre Lehrerkolleginnen und -kollegen sehen ihn nicht.',
  'admin.site.intro': 'Was für alle Schulen zugleich gilt und damit für keine im Besonderen: Schulen anlegen, Modellstufen und -katalog einstellen, Rechnungen, offene Posten und Tarife verfolgen.',
  'admin.site.elsewhere': 'Die übrigen Verwaltungen haben ihre eigene Tür:',
