  'admin.zone.moderation': 'Der Katalog der Plattform',
  'admin.denied.siteOnly': 'Diese Seite gehört der PLATTFORM: Schulen, Modellstufen und -katalog, Rechnungen und Tarife. Die Verwaltung Ihrer eigenen Schule liegt auf der Seite der Schule.',
  'admin.denied.toSchool': 'Meine Schule verwalten',
  'admin.credit.helpSite': 'Aus Sicht der Plattform: der Saldo jeder Schule, ihre geschätzte Reichweite und jene, die aufgebraucht sind. Aufladen und Korrigieren geschieht hier; der Beitragssatz dagegen gehört der Schule und wird bei ihr eingestellt.',
  'admin.credit.empty': 'Kein Guthaben anzuzeigen.',
