  'admin.facture.billingEmail': 'Rechnungskontakt',
  'ens.moderation.title': 'Die Tutoren Ihrer Schule',
  'ens.moderation.help': 'Lesen, korrigieren und freigeben, was Ihre Kolleginnen und Kollegen hier vorschlagen, und die Kommentare auf diesen Seiten moderieren. Offen für JEDE Lehrperson der aktiven Schule: das ist keine Verwaltungsbefugnis, sondern eine kollegiale Geste.',
  'ens.school.title': 'Die Verwaltung der Schule',
  'ens.school.help': 'Guthaben, Konten, Rechnung und Schulkatalog liegen nicht hier: sie stehen auf der Seite der Schule, zusammen mit ihren Zeiten und Kontingenten.',
  'ens.school.cta': 'Schulbereich öffnen',
  'etab.readOnly': 'Sie gehören zu dieser Schule, ohne sie zu administrieren: die Einstellungen unten werden angezeigt, ändern kann sie aber nur die Schulverwaltung.',
  'etab.zone.wallet': 'Guthaben und Aufladen',
  'etab.zone.invoice': 'Rechnung der Schule',
  'etab.zone.accounts': 'Konten der Schule',
  'etab.zone.accountsHelp': 'Wer hier unterrichtet, wer verwaltet, und für wen die Schule die Volljährigkeit bezeugt. Ein Konto wird nie gelöscht: ihm die Rollen zu entziehen schliesst bereits jedes Schreibrecht.',
  'etab.zone.tutors': 'Tutoren der Schule',
  'etab.zone.tutorsHelp': 'Zwei Türen: was Ihre Lernenden von anderen Schulen sehen, und was Ihre nach aussen zeigt — Tutor für Tutor, geschlossen, solange Sie sie nicht öffnen.',
  'etab.usage.scope': 'Aufgeführt sind die Anbieter, die der Schlüssel Ihrer Schule nutzen kann: eine Null bedeutet «diesen Monat nichts verbraucht», keine Störung.',
  'etab.usage.notServed': 'nicht mehr verfügbar',
  'etab.usage.notServedTitle': 'Dieser Anbieter wurde mit dem Schlüssel der Schule genutzt, kann heute aber nicht mehr bedient werden. Diese Token wurden tatsächlich abgerechnet – die Zeile bleibt.',
