  'tour.ecole.selecteur': 'Ein Konto kann an mehreren Schulen unterrichten. Diese Auswahl sagt, von welcher der Rest der Seite spricht — und der Rang daneben, Administratorin oder Mitglied, erklärt, warum manche Abschnitte erscheinen und andere nicht.',
  'tour.session.providers': 'Die Anbieter, die der Schlüssel der Schule während der Lektion bedient. Alle abzuwählen ist eine legitime Wahl, und sie schliesst: der Schlüssel der Schule bedient dann nichts mehr. Der Filter gilt nur für ihn — wer den eigenen mitbringt, hängt nicht davon ab.',
  'tour.session.school': 'Guthaben, Konten, Rechnung und das Teilen der Tutoren werden nicht hier eingestellt: Sie gehören der Schule und leben auf ihrer eigenen Seite. Diese Schaltfläche führt dorthin, für alle, die sie administrieren.',
  'tour.etab.wallet': 'Das Guthaben der Schule: ihr Saldo, die Ausgaben der letzten dreissig Tage, die Reichweite, die ihr das lässt, und der datierte Verlauf jeder Bewegung. Der Schieberegler stellt den Beitrag an die Kosten ein, zwischen 3,5 und 10 % — die Schule wählt. Die hier gezeigten Zahlen sind erfunden.',
